insert into distributor_accounts(distributor_id,distributor_name,identity_key,assigned_to,installation_status,training_status,activity_status,billing_status,created_by,updated_at,renewal_date)
select gen_random_uuid(),'Scale '||n,'name:scale-'||n,case when n%2=0 then '20000000-0000-4000-a000-000000000001'::uuid else '20000000-0000-4000-a000-000000000002'::uuid end,'done','done',case when n%3=0 then 'inactive' else 'active' end,case when n%4=0 then 'billed' else 'not_billed' end,'10000000-0000-4000-a000-000000000001',clock_timestamp()-make_interval(secs=>n),(current_date+(n%30)) from generate_series(1,10000)n;
do $$declare plan json;begin execute 'explain (format json) select distributor_id,distributor_name,assigned_to,renewal_date,updated_at from distributor_accounts order by updated_at desc,distributor_id desc limit 50' into plan;if plan::text not like '%distributor_list_updated_idx%' then raise exception 'list index not used: %',plan;end if;end$$;
